"code": "obs_list, act_list = [], []\nfor day in range(7):\n    env = OxygenTank(\"dry\", day=day, seed=day)\n    o, done = env.reset(), False\n    while not done:\n        a = pid_policy(o)\n        obs_list.append(o); act_list.append(a / 20.0)          # scale the action to [−1, 1]\n        o, _, done, _ = env.step(a)\nXd = torch.tensor(np.array(obs_list), dtype=torch.float32)\nyd = torch.tensor(np.array(act_list), dtype=torch.float32)[:, None]\nprint(\"demonstrations:\", Xd.shape, \"→\", yd.shape)\n\ntorch.manual_seed(0)\nbc = nn.Sequential(nn.Linear(4, 32), nn.ReLU(), nn.Linear(32, 32), nn.ReLU(), nn.Linear(32, 1), nn.Tanh())\nopt = torch.optim.Adam(bc.parameters(), lr=3e-3)\nfor it in range(3000):\n    idx = torch.randint(0, len(Xd), (256,))\n    loss = ((bc(Xd[idx]) - yd[idx]) ** 2).mean()               # plain regression, as in pretrain_bc\n    opt.zero_grad(); loss.backward(); opt.step()\n    if it % 1000 == 0 or it == 2999:\n        print(f\"step {it:4d}  imitation loss {loss.item():.5f}\")\n\n\ndef bc_policy(o):\n    with torch.no_grad():\n        return 20.0 * float(bc(torch.tensor(o, dtype=torch.float32)))\n\nres_bc = run(OxygenTank(\"dry\", day=10), bc_policy)\nprint(f\"\\nimitation  return {res_bc['return']:.1f}   mean |S_O − 2| {res_bc['oxygen error']:.3f}   (PID: {res_pid['oxygen error']:.3f})\")",
